// Package Vite's production output as one HTML document for Streamlit's iframe.
// This generated file is committed so Streamlit Cloud does not need Node.js.
import {readFile, writeFile, mkdir} from 'node:fs/promises';
import {resolve} from 'node:path';
const root = resolve(import.meta.dirname, '..');
let html = await readFile(resolve(root, 'dist/index.html'), 'utf8');
const asset = path => readFile(resolve(root, 'dist', path.replace(/^\//, '')), 'utf8');
const jsTag = /<script\b[^>]*src="([^"]+)"[^>]*><\/script>/g;
const cssTag = /<link\b[^>]*rel="stylesheet"[^>]*href="([^"]+)"[^>]*>/g;
for (const match of [...html.matchAll(jsTag)]) {
  const js = await asset(match[1]);
  html = html.replace(match[0], () => `<script type="module">${js.replace(/<\/script/gi, '<\\/script')}</script>`);
}
for (const match of [...html.matchAll(cssTag)]) {
  const css = await asset(match[1]);
  html = html.replace(match[0], () => `<style>${css.replace(/<\/style/gi, '<\\/style')}</style>`);
}
await mkdir(resolve(root, 'streamlit_assets'), {recursive:true});
await writeFile(resolve(root, 'streamlit_assets/site.html'), '<!-- Generated by npm run build; edit src/ instead. -->\n'+html);
console.log('Built streamlit_assets/site.html (self-contained frontend)');
